-- Personalised document list: each document can be tied to a situation (wealth event, spouse, children, corporation).
-- situations NULL/empty = sent by everyone. description = why we ask, shown to the client.
ALTER TABLE public.intake_checklist_templates
  ADD COLUMN IF NOT EXISTS situations text[],
  ADD COLUMN IF NOT EXISTS description text;

-- A new client is finished once documents are confirmed AND the Survey Session is booked, in either order.
ALTER TABLE public.households ADD COLUMN IF NOT EXISTS documents_completed_at timestamptz;
UPDATE public.households SET documents_completed_at = onboarding_completed_at
  WHERE onboarding_completed_at IS NOT NULL AND documents_completed_at IS NULL AND COALESCE(legacy_intake_upgrade, false) = false;

